def _verify_bipartite(adj_list):
    """Verify that a graph is actually bipartite by attempting to 2-color it."""
    if not adj_list:
        return True

    color = {}
    for start in adj_list:
        if start in color:
            continue

        queue = [start]
        color[start] = 0

        while queue:
            node = queue.pop(0)
            current_color = color[node]

            for neighbor in adj_list.get(node, []):
                if neighbor not in color:
                    color[neighbor] = 1 - current_color
                    queue.append(neighbor)
                elif color[neighbor] == current_color:
                    return False

    return True

def _can_two_color(adj_list):
    """Helper to verify if graph is bipartite via 2-coloring"""
    if not adj_list:
        return True
    color = {}
    for start in adj_list:
        if start in color:
            continue
        queue = [start]
        color[start] = 0
        while queue:
            node = queue.pop(0)
            for neighbor in adj_list.get(node, []):
                if neighbor not in color:
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False
    return True

